<template><div class="page"><div class="page-title"><h2>联动指令</h2><el-button type="primary" :disabled="!canWrite()" @click="dialog=true">新建指令</el-button></div><div class="panel"><el-table :data="rows" stripe><el-table-column prop="actionNo" label="指令号" /><el-table-column prop="type" label="类型" /><el-table-column prop="targetKey" label="对象" /><el-table-column prop="status" label="状态" /><el-table-column prop="resultMessage" label="结果" /><el-table-column label="操作"><template #default="{row}"><el-button link @click="retry(row)">重试</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" title="创建联动指令"><el-form label-width="90px"><el-form-item label="类型"><el-select v-model="form.type" style="width:100%"><el-option v-for="item in types" :key="item.type" :label="item.name || item.type" :value="item.type" /></el-select></el-form-item><el-form-item label="对象"><el-input v-model="form.targetKey" /></el-form-item><el-form-item label="参数 JSON"><el-input v-model="form.params" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">执行</el-button></template></el-dialog></div></template>
<script setup>
import { reactive, ref } from 'vue'; import { actionApi } from '../api'; import { canWrite } from '../auth'; import { ElMessage } from 'element-plus'
const rows=ref([]),types=ref([]),dialog=ref(false),form=reactive({type:'OMS_HOLD',targetKey:'',params:'{}'}); async function load(){ rows.value=await actionApi.page(); types.value=await actionApi.types() }; async function create(){ await actionApi.create({ ...form, params:JSON.parse(form.params||'{}') }); dialog.value=false; ElMessage.success('指令已创建'); load() }; async function retry(row){await actionApi.retry(row.id);load()}; load()
</script>
